package run.ikaros.finance; import java.time.YearMonth; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/v2/finance/ledgers/{ledgerId}") public class FinanceStatisticsController{private final FinanceStatisticsService service;public FinanceStatisticsController(FinanceStatisticsService s){service=s;}@GetMapping("/statistics/monthly")public Mono<MonthlyStatisticsView> month(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId,@RequestParam YearMonth month){return service.month(a,ledgerId,month);}@GetMapping("/transactions/search")public Flux<TransactionView> search(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId,@RequestParam String q){return service.search(a,ledgerId,q);}}
